 return header(def.title,def.kind==='baseline'?'Starting check':def.kind==='mock'?'Mock paper':'Reasoning paper')+`<div class="sp-paper-meta"><strong>Question ${p.index+1} of ${qs.length}</strong><span id="spPaperClock" role="timer">${p.deadline?'Time remaining':'Untimed'}</span><span>${p.assisted||p.interrupted?'Supported practice':'No hints or feedback until submission'}</span></div><div class="sp-paper-map" aria-label="Question navigation">${qs.map((_,i)=>`<button data-paper-index="${i}" aria-label="Question ${i+1}${E.B.validAnswer(qs[i],p.answers[i]?.answer)?' answered':''}${p.flags.includes(i)?', marked for later':''}" ${p.index===i?'aria-current="step"':''} data-answered="${E.B.validAnswer(qs[i],p.answers[i]?.answer)}">${i+1}${p.flags.includes(i)?' *':''}</button>`).join('')}</div><article class="sp-question-sheet"><p class="sp-question-text">${esc(q.text)}</p>${F.diagram(q.figure,q.id)}${editor(q,saved,true)}<div class="sp-actions"><button id="spPaperPrev" ${p.index===0?'disabled':''}>Previous</button><button id="spPaperFlag">${p.flags.includes(p.index)?'Unmark':'Mark for later'}</button><button id="spPaperNext" ${p.index===qs.length-1?'disabled':''}>Next</button><button id="spSubmitPaper" class="sp-primary">Submit paper</button></div><p class="sp-note" id="spPaperSave">Answers and working save as you go. Submission freezes the paper.</p></article><button id="spPausePaper">Pause & use as practice</button><p class="sp-scope">Original practice format; not an official NUS High examination. The timer continues if this page is hidden.</p>`;
